import random

def scramble_word(word):
    """Scramble a word by randomly swapping characters."""
    scrambled = list(word)
    random.shuffle(scrambled)
    return ''.join(scrambled)

def unscramble_word(scrambled_word):
    """Unscramble a word by swapping characters in the correct order."""
    word = list(scrambled_word)
    for i in range(len(word)):
        for j in range(i + 1, len(word)):
            if word[i] == scrambled_word[j]:
                word[i], word[j] = word[j], word[i]
                break
    return ''.join(word)

def main():
    while True:
        scrambled_word = scramble_word(input("Enter a scrambled word: "))
        user_input = input(f"The scrambled word is '{scrambled_word}'. Please unscramble it: ")
        if user_input.upper() == unscramble_word(scrambled_word).upper():
            print("Correct!")
            print(f"The unscrambled word is '{unscramble_word(scrambled_word)}'.")
            break
        else:
            print("Incorrect. Please try again.")

if __name__ == "__main__":
    main()
```
This program defines three functions: `scramble_word`, `unscramble_word`, and `main`. The `scramble_word` function randomly swaps characters in a word, while the `unscramble_word` function swaps characters in the correct order to unscramble the word. The `main` function starts an infinite loop, prompting the user to enter a scrambled word and then asking them to unscramble it. If the user's input matches the unscrambled word, the program prints a congratulatory message. Otherwise, it prints an error message and continues prompting the user for input.
